//! Staged container file transfers: export to a host/remote staging path,
//! import back into a container, cleanup and local save helpers.
//!
//! Staging paths are always generated by this feature: remote paths live
//! under `/tmp/dbx-sshx.<token>`, local paths under the system temp dir in a
//! `dbx-sshx-<uuid>` directory. [`validate_staging_path`] is the only gate
//! cleanup, import and saveLocal ever consult, so an arbitrary path can
//! never be deleted, copied out of, or imported from.

use super::*;

use std::path::{Component, Path, PathBuf};

use uuid::Uuid;

/// Wait cap for one `docker cp` leg (a large file can take a while).
pub const TRANSFER_TIMEOUT: Duration = Duration::from_secs(300);
/// Remote staging root: `/tmp/dbx-sshx.<mktemp token>`.
pub const REMOTE_STAGING_PREFIX: &str = "/tmp/dbx-sshx.";
/// Local staging directory prefix under the system temp dir.
pub const LOCAL_STAGING_PREFIX: &str = "dbx-sshx-";

/// Where a staging path lives: the remote host or the sidecar machine.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum StagingLocation {
    Remote,
    Local,
}

/// Validates a staging path against its generated-prefix contract.
pub fn validate_staging_path(path: &str, location: StagingLocation) -> Result<(), String> {
    if path.is_empty() || path.chars().any(char::is_control) {
        return Err("Invalid staging path".to_string());
    }
    match location {
        StagingLocation::Remote => validate_remote_staging(path),
        StagingLocation::Local => validate_local_staging(path),
    }
}

/// Remote staging paths: `/tmp/dbx-sshx.<token>` optionally followed by one
/// file name. `.`/`..` segments and deeper nesting are rejected, so the
/// path can only point inside this feature's generated directory.
fn validate_remote_staging(path: &str) -> Result<(), String> {
    if !path.starts_with(REMOTE_STAGING_PREFIX) {
        return Err(format!(
            "Staging path must start with '{REMOTE_STAGING_PREFIX}'"
        ));
    }
    let segments: Vec<&str> = path.split('/').filter(|segment| !segment.is_empty()).collect();
    // ["tmp", "dbx-sshx.<token>", "<file>"?]
    if segments.len() < 2 || segments.len() > 3 || segments[0] != "tmp" {
        return Err("Staging path must be a file inside /tmp/dbx-sshx.<token>".to_string());
    }
    let dir = segments[1];
    if !dir.starts_with("dbx-sshx.") || dir.len() <= "dbx-sshx.".len() {
        return Err("Staging directory was not generated by this feature".to_string());
    }
    if segments
        .iter()
        .any(|segment| *segment == "." || *segment == "..")
    {
        return Err("Staging path must not contain '.' or '..' segments".to_string());
    }
    Ok(())
}

/// Local staging paths: an absolute path lexically inside the system temp
/// dir whose first generated component is `dbx-sshx-<token>`. The generated
/// directory itself and one file below it are accepted; anything deeper is
/// rejected.
fn validate_local_staging(path: &str) -> Result<(), String> {
    let candidate = Path::new(path);
    if !candidate.is_absolute() {
        return Err("Staging path must be absolute".to_string());
    }
    let normalized = lexical_absolute(candidate);
    let base = lexical_absolute(&std::env::temp_dir());
    let relative = normalized
        .strip_prefix(&base)
        .map_err(|_| "Staging path must live in the system temp directory".to_string())?;
    let components: Vec<Component> = relative.components().collect();
    let dir_name = match components.as_slice() {
        [] => candidate.file_name().map(|name| name.to_string_lossy().into_owned()),
        [Component::Normal(name)] => Some(name.to_string_lossy().into_owned()),
        [Component::Normal(name), Component::Normal(_)] => {
            Some(name.to_string_lossy().into_owned())
        }
        _ => None,
    }
    .ok_or_else(|| "Staging path must stay inside one generated directory".to_string())?;
    if !dir_name.starts_with(LOCAL_STAGING_PREFIX) || dir_name.len() <= LOCAL_STAGING_PREFIX.len() {
        return Err("Staging directory was not generated by this feature".to_string());
    }
    Ok(())
}

/// Lexical absolute normalization (resolves `.`/`..` without touching the
/// filesystem, so deleted staging files still validate during cleanup).
fn lexical_absolute(path: &Path) -> PathBuf {
    let mut out = PathBuf::new();
    for component in path.components() {
        match component {
            Component::Prefix(prefix) => out.push(prefix.as_os_str()),
            Component::RootDir => out.push(component.as_os_str()),
            Component::CurDir => {}
            Component::ParentDir => {
                out.pop();
            }
            Component::Normal(part) => out.push(part),
        }
    }
    out
}

/// The generated directory owning a validated local staging path.
pub fn local_staging_dir(path: &Path) -> PathBuf {
    if path.is_dir() {
        return path.to_path_buf();
    }
    path.parent().map(Path::to_path_buf).unwrap_or_default()
}

/// Safe staging file name: the container path's basename with command- and
/// protocol-breaking characters replaced. Empty names become `download`.
pub fn safe_staging_name(path: &str) -> String {
    let trimmed = path.trim_end_matches('/');
    let base = trimmed.rsplit('/').next().unwrap_or_default();
    let cleaned: String = base
        .chars()
        .map(|character| match character {
            '/' | '\\' | '\0' | '\r' | '\n' => '_',
            other => other,
        })
        .collect();
    let cleaned = cleaned.trim();
    if cleaned.is_empty() || cleaned == "." || cleaned == ".." {
        "download".to_string()
    } else {
        cleaned.to_string()
    }
}

/// Import destination semantics: a `destPath` ending in `/` is a directory
/// and keeps the staging file name; anything else is the full target path.
pub fn resolve_import_dest(dest_path: &str, name: &str) -> Result<String, String> {
    let normalized = normalize_container_path(dest_path)?;
    if dest_path.ends_with('/') {
        Ok(join_container_path(&normalized, &safe_staging_name(name)))
    } else {
        Ok(normalized)
    }
}

/// Remote temp directory creation command (0700 by `umask` and `mktemp -d`).
pub fn mktemp_command() -> String {
    "umask 077 && mktemp -d /tmp/dbx-sshx.XXXXXX".to_string()
}

/// Extracts and validates the directory printed by [`mktemp_command`].
pub fn parse_mktemp_output(output: &str) -> Result<String, String> {
    let dir = output
        .lines()
        .map(str::trim)
        .filter(|line| !line.is_empty())
        .last()
        .ok_or("Failed to create a staging directory")?
        .to_string();
    validate_staging_path(&dir, StagingLocation::Remote)
        .map_err(|error| format!("Unexpected staging directory '{dir}': {error}"))?;
    Ok(dir)
}

/// `docker cp <id>:<container path> <staging path>` for the SSH plane.
pub fn export_command(
    engine: &EngineConfig,
    container_id: &str,
    container_path: &str,
    staging_path: &str,
) -> Result<String, String> {
    validate_container_id(container_id)?;
    let container_path = normalize_container_path(container_path)?;
    validate_staging_path(staging_path, StagingLocation::Remote)?;
    Ok(format!(
        "{}{} cp {} {}",
        engine.env_prefix(),
        engine.cli,
        exec::shell_quote(&format!("{container_id}:{container_path}")),
        exec::shell_quote(staging_path)
    ))
}

/// `docker cp <staging path> <id>:<dest>` for the SSH plane.
pub fn import_command(
    engine: &EngineConfig,
    container_id: &str,
    staging_path: &str,
    dest_path: &str,
) -> Result<String, String> {
    validate_container_id(container_id)?;
    validate_staging_path(staging_path, StagingLocation::Remote)?;
    let dest_path = normalize_container_path(dest_path)?;
    Ok(format!(
        "{}{} cp {} {}",
        engine.env_prefix(),
        engine.cli,
        exec::shell_quote(staging_path),
        exec::shell_quote(&format!("{container_id}:{dest_path}"))
    ))
}

/// Cleanup command for a validated remote staging file (removes the file
/// and its generated directory). A directory path removes itself.
pub fn cleanup_command(staging_path: &str) -> Result<String, String> {
    validate_staging_path(staging_path, StagingLocation::Remote)?;
    let segments = staging_path.split('/').filter(|segment| !segment.is_empty()).count();
    if segments <= 2 {
        return Ok(format!("rm -rf -- {}", exec::shell_quote(staging_path)));
    }
    Ok(format!(
        "rm -f -- {}; rmdir -- {}",
        exec::shell_quote(staging_path),
        exec::shell_quote(parent_container_path(staging_path))
    ))
}

/// Creates the local staging directory (`<temp>/dbx-sshx-<uuid>`, 0700).
pub fn create_local_staging_dir() -> Result<PathBuf, String> {
    let dir = std::env::temp_dir().join(format!("{LOCAL_STAGING_PREFIX}{}", Uuid::new_v4()));
    std::fs::create_dir_all(&dir)
        .map_err(|error| format!("Failed to create staging directory: {error}"))?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(&dir, std::fs::Permissions::from_mode(0o700))
            .map_err(|error| format!("Failed to secure staging directory: {error}"))?;
    }
    Ok(dir)
}

/// `docker cp` on the local plane (argv only), returning the staged size.
pub async fn export_local(
    engine: &EngineConfig,
    container_id: &str,
    container_path: &str,
    staging_path: &str,
) -> Result<u64, String> {
    validate_container_id(container_id)?;
    let container_path = normalize_container_path(container_path)?;
    validate_staging_path(staging_path, StagingLocation::Local)?;
    let source = format!("{container_id}:{container_path}");
    local_cp(engine, &source, staging_path).await?;
    std::fs::metadata(staging_path)
        .map(|meta| meta.len())
        .map_err(|error| format!("Failed to read staged file: {error}"))
}

/// `docker cp` staging → container on the local plane (argv only).
pub async fn import_local(
    engine: &EngineConfig,
    staging_path: &str,
    container_id: &str,
    dest_path: &str,
) -> Result<(), String> {
    validate_container_id(container_id)?;
    validate_staging_path(staging_path, StagingLocation::Local)?;
    let dest_path = normalize_container_path(dest_path)?;
    let dest = format!("{container_id}:{dest_path}");
    local_cp(engine, staging_path, &dest).await
}

async fn local_cp(engine: &EngineConfig, source: &str, dest: &str) -> Result<(), String> {
    let cli = find_local_cli(&engine.cli)
        .ok_or_else(|| format!("{} CLI not found on this machine", engine.cli))?;
    let (exit_code, output) = run_local(
        &cli,
        &["cp", source, dest],
        TRANSFER_TIMEOUT,
        engine.endpoint.as_deref(),
    )
    .await?;
    if exit_code != 0 {
        return Err(format!(
            "{} cp failed (exit {exit_code}): {output}",
            engine.cli
        ));
    }
    Ok(())
}

/// Removes a validated local staging file and its generated directory.
/// Cleanup is best-effort: a failure never changes the transfer result.
pub fn cleanup_local(staging_path: &str) -> bool {
    if validate_staging_path(staging_path, StagingLocation::Local).is_err() {
        return false;
    }
    let path = Path::new(staging_path);
    if path.is_dir() {
        let _ = std::fs::remove_dir_all(path);
        return true;
    }
    let _ = std::fs::remove_file(path);
    let _ = std::fs::remove_dir(local_staging_dir(path));
    true
}

/// Structured audit row for an import: tool, container, destination and
/// size only — never file contents. Written before the copy so an aborted
/// import still leaves its intent on the ledger.
pub fn audit_import(data_dir: &Path, container_id: &str, dest_path: &str, size: u64) {
    let ts_ms = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|duration| duration.as_millis() as u64)
        .unwrap_or_default();
    let entry = audit_log::AuditEntry {
        ts_ms,
        tool: "docker/files/import".to_string(),
        connection_id: String::new(),
        gate: audit_log::GateOutcome::Pass,
        approval: audit_log::ApprovalTrail::None,
        outcome: audit_log::EntryOutcome::Ok,
        exit_code: None,
        duration_ms: 0,
        mode: audit_log::ExecMode::Stdio,
        command: Some(format!(
            "docker/files/import containerId={container_id} destPath={dest_path} size={size}"
        )),
        output: None,
        error: None,
    };
    if let Err(error) = audit_log::append(data_dir, &entry) {
        eprintln!("[docker] import audit append failed: {error}");
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn staging_paths_only_accept_generated_prefix() {
        assert!(validate_staging_path("/tmp/dbx-sshx.1234/report.log", StagingLocation::Remote).is_ok());
        assert!(validate_staging_path("/etc/passwd", StagingLocation::Remote).is_err());
        assert!(validate_staging_path("/tmp/other/report.log", StagingLocation::Remote).is_err());
        assert!(validate_staging_path("/tmp/dbx-sshx.1234/../etc/passwd", StagingLocation::Remote).is_err());
    }

    #[test]
    fn import_destination_keeps_name_for_directory_targets() {
        assert_eq!(
            resolve_import_dest("/srv/app/", "report.log").unwrap(),
            "/srv/app/report.log"
        );
        assert_eq!(
            resolve_import_dest("/srv/app/report.log", "ignored").unwrap(),
            "/srv/app/report.log"
        );
    }

    #[test]
    fn safe_names_strip_separators_and_fall_back() {
        assert_eq!(safe_staging_name("/var/log/app.log"), "app.log");
        assert_eq!(safe_staging_name("/var/log/../../etc/passwd"), "passwd");
        assert_eq!(safe_staging_name("/"), "download");
        assert_eq!(safe_staging_name("/tmp/a\r\nb"), "a__b");
        assert_eq!(safe_staging_name("a/b\\c"), "b_c");
    }

    #[test]
    fn local_staging_paths_are_confined_to_the_generated_dir() {
        let dir = std::env::temp_dir().join("dbx-sshx-test");
        let file = dir.join("report.log");
        assert!(validate_staging_path(file.to_str().unwrap(), StagingLocation::Local).is_ok());
        assert!(validate_staging_path(dir.to_str().unwrap(), StagingLocation::Local).is_ok());
        assert!(validate_staging_path("/etc/passwd", StagingLocation::Local).is_err());
        assert!(validate_staging_path(
            &format!("{}/../escape", dir.display()),
            StagingLocation::Local
        )
        .is_err());
        assert!(validate_staging_path(
            &dir.join("nested/escape").to_string_lossy(),
            StagingLocation::Local
        )
        .is_err());
    }

    #[test]
    fn remote_commands_quote_staged_paths() {
        let engine = test_engine("docker", None);
        let export = export_command(&engine, "d4a7c9f1e2b3", "/tmp/a b", "/tmp/dbx-sshx.1/f")
            .unwrap();
        assert_eq!(
            export,
            "docker cp 'd4a7c9f1e2b3:/tmp/a b' '/tmp/dbx-sshx.1/f'"
        );
        let import = import_command(&engine, "d4a7c9f1e2b3", "/tmp/dbx-sshx.1/f", "/srv/it's")
            .unwrap();
        assert_eq!(
            import,
            "docker cp '/tmp/dbx-sshx.1/f' 'd4a7c9f1e2b3:/srv/it'\\''s'"
        );
        let cleanup = cleanup_command("/tmp/dbx-sshx.1/f").unwrap();
        assert_eq!(
            cleanup,
            "rm -f -- '/tmp/dbx-sshx.1/f'; rmdir -- '/tmp/dbx-sshx.1'"
        );
        assert!(cleanup_command("/etc/passwd").is_err());
        assert!(import_command(&engine, "d4a7c9f1e2b3", "/etc/passwd", "/srv/x").is_err());
    }
}
